class Library:
    def __init__(self):
        self._copies = {}            # title -> how many copies the library owns
        self._out = {}               # title -> how many of them are borrowed

    def add_book(self, title, copies=1):
        self._copies[title] = self._copies.get(title, 0) + copies
        self._out.setdefault(title, 0)

    def available(self, title):
        return self._copies.get(title, 0) - self._out.get(title, 0)

    def borrow(self, title):
        if self.available(title) < 1:
            return False
        self._out[title] += 1
        return True

    def return_book(self, title):
        if self._out.get(title, 0) < 1:
            return False
        self._out[title] -= 1
        return True
